const out = [];
for (const it of $input.all()) {
  const p = it.json || {};
  const raw = String(p.output || '').trim();
  let parsed = {};
  try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
  const base = $('Normalize New Agreement').first().json || {};
  out.push(Object.assign({}, base, { email_subject: parsed.subject || ('Welcome to your maintenance plan, ' + base.customer_name), email_body: parsed.body || raw, ai_raw: raw.slice(0, 600) }));
}
return out;

const rows = ($input.all() || []).map(r => (r.json || {})).filter(r => r && String(r.customer_name || '').trim() && String(r.customer_email || '').trim());
const out = [];
const now = new Date();
now.setHours(0, 0, 0, 0);
for (const r of rows) {
  const status = String(r.status || 'active').trim();
  if (status !== 'active') { continue; }
  const dueRaw = String(r.next_due_date || '').trim();
  let daysLeft = 999;
  if (dueRaw) {
    const d = new Date(dueRaw.length === 10 ? dueRaw + 'T00:00:00' : dueRaw);
    if (!isNaN(d.getTime())) { d.setHours(0, 0, 0, 0); daysLeft = Math.floor((d.getTime() - now.getTime()) / 86400000); }
  }
  if (daysLeft <= 3) {
    out.push(Object.assign({}, r, { days_left: daysLeft, is_overdue: daysLeft < 0 ? 'yes' : 'no', office_email: r.office_email || 'user@example.com' }));
  }
}
return out.map(x => ({ json: x }));

const flags = ($('Flag Due Agreements').all() || []).map(r => r.json || {});
const out = [];
let i = 0;
for (const it of $input.all()) {
  const p = it.json || {};
  const raw = String(p.output || '').trim();
  let parsed = {};
  try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
  const base = (flags[i] || {});
  out.push(Object.assign({}, base, { email_subject: parsed.subject || ('Service due: ' + base.customer_name), email_body: parsed.body || raw }));
  i += 1;
}
return out;

// after customer reminders: if any flagged item is overdue, emit ONE office email payload
const flags = ($('Flag Due Agreements').all() || []).map(r => r.json || {});
const office = (flags[0] || {}).office_email || 'user@example.com';
const overdue = flags.filter(f => String(f.is_overdue || '') === 'yes');
if (overdue.length === 0) { return []; }
const lines = overdue.map(o => 'Customer ' + o.customer_name + ' (' + o.customer_email + ') service was due ' + o.next_due_date + ', ' + String(-1 * o.days_left) + ' day(s) overdue' + (o.customer_phone ? ', phone ' + o.customer_phone : ''));
const body = ['The following maintenance agreements are overdue for service:', '', ...lines, '', 'Please call each customer and book the visit as soon as possible.'].join(String.fromCharCode(10));
return [{ json: { office_email: office, overdue_count: overdue.length, overdue_subject: 'Overdue HVAC services: ' + overdue.length + ' customer(s)', overdue_body: body } }];

const rows = ($input.all() || []).map(r => (r.json || {})).filter(r => r && String(r.customer_name || '').trim());
if (rows.length === 0) { return []; }
const office = (rows[0] || {}).office_email || 'user@example.com';
const now = new Date();
now.setHours(0, 0, 0, 0);
const active = rows.filter(r => String(r.status || 'active').trim() === 'active');
let dueWeek = [], overdue = [], renewSoon = [];
const days = (s) => { const d = new Date(String(s || '').length === 10 ? String(s) + 'T00:00:00' : String(s || '')); if (isNaN(d.getTime())) return 999; d.setHours(0, 0, 0, 0); return Math.floor((d.getTime() - now.getTime()) / 86400000); };
for (const r of active) {
  const dl = days(r.next_due_date);
  if (dl <= 7) { dueWeek.push({ n: r.customer_name, due: r.next_due_date, left: dl }); }
  if (dl < 0) { overdue.push({ n: r.customer_name, due: r.next_due_date, left: dl }); }
  const re = days(r.agreement_end_date);
  if (re >= 0 && re <= 60) { renewSoon.push({ n: r.customer_name, end: r.agreement_end_date }); }
}
const list = active.map(r => ({ n: r.customer_name, system: r.system_type || 'HVAC', next: r.next_due_date || '', end: r.agreement_end_date || '' }));
return [{ json: { office_email: office, active_count: active.length, total_rows: rows.length, due_week_count: dueWeek.length, due_week_json: JSON.stringify(dueWeek), overdue_count: overdue.length, overdue_json: JSON.stringify(overdue), renew_soon_count: renewSoon.length, renew_json: JSON.stringify(renewSoon), rows_json: JSON.stringify(list), week_label: new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date()) } }];

const out = [];
for (const it of $input.all()) {
  const p = it.json || {};
  const raw = String(p.output || '').trim();
  let parsed = {};
  try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
  const base = $('Collate Agreement Stats').first().json || {};
  out.push(Object.assign({}, base, { email_subject: parsed.subject || ('Weekly maintenance review ' + base.week_label), email_body: parsed.body || raw }));
}
return out;
